use rusted_core::{Settings,ThemeName,ViewMode,Workspace};
use rusted_db::{Database,Profile};
#[test]fn settings_theme_and_session_roundtrip(){let db=Database::in_memory().unwrap();let mut settings=Settings::default();settings.theme=ThemeName::Snow;db.save_settings(&settings).unwrap();assert_eq!(db.load_settings().unwrap().unwrap().theme,ThemeName::Snow);let mut workspace=Workspace::new(".".into(),ViewMode::Details);workspace.new_tab("..".into(),ViewMode::Grid);db.save_session("autosave",&workspace).unwrap();let restored=db.load_session("autosave").unwrap().unwrap();assert_eq!(restored.active_pane().tabs.len(),2);assert_eq!(restored.active_tab().view,ViewMode::Grid);}
#[test]fn bookmarks_tags_recents_and_profiles_persist(){let db=Database::in_memory().unwrap();db.pin(std::path::Path::new("/tmp/a"),"A","Custom").unwrap();db.tag(std::path::Path::new("/tmp/a"),"work","#aaaaaa").unwrap();db.visit(std::path::Path::new("/tmp/a")).unwrap();assert_eq!(db.bookmarks().unwrap().len(),1);assert_eq!(db.tags(Some("work")).unwrap().len(),1);assert_eq!(db.recent_locations(10).unwrap().len(),1);let profile=Profile{name:"Work".into(),workspace:Workspace::new("/tmp".into(),ViewMode::List),settings:Settings::default()};db.save_profile(&profile).unwrap();assert_eq!(db.load_profile("Work").unwrap().unwrap().workspace.active_tab().view,ViewMode::List);}
